import{_ as s,o as n,c as e,ag as t}from"./chunks/framework.DoUXNnsN.js";const h=JSON.parse('{"title":"Git冲突与撤销","description":"","frontmatter":{"title":"Git冲突与撤销","aliases":["merge conflict","合并冲突","git restore","git reset","git revert","git reflog","git stash","git commit --amend","后悔药"],"tags":["工具与工程","Git"],"status":"ai-draft","sources":["https://git-scm.com/book/zh/v2/Git-工具-重置揭秘","https://git-scm.com/docs/git-reflog","https://git-scm.com/docs/git-restore","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":5},"headers":[],"relativePath":"50-工具与工程/Git/Git冲突与撤销.md","filePath":"50-工具与工程/Git/Git冲突与撤销.md"}'),p={name:"50-工具与工程/Git/Git冲突与撤销.md"};function o(i,a,c,d,l,r){return n(),e("div",null,[...a[0]||(a[0]=[t(`<blockquote><p>本篇是 <a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a> 入门路径的第 5 篇。读完你应该能：看懂冲突标记并亲手解决一次合并冲突；根据&quot;改动在哪个区、有没有推送&quot;选对撤销命令（<code>restore</code> / <code>reset</code> / <code>revert</code> / <code>amend</code>）；用 <code>reflog</code> 找回&quot;丢掉&quot;的提交和被误删的分支。</p><p>所有命令和输出在 Windows 11 + Git for Windows 2.54.0（Git Bash）里实际运行。文中用 <code>sed -i</code> 修改文件，这是 Git Bash 自带的命令；在 PowerShell 里请直接用编辑器改。哈希每次不同。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p><strong>冲突</strong>是两条分支改了同一处内容，Git 无法自动判断保留哪边，需要你人工决定；<strong>撤销</strong>是一组后悔药，按&quot;撤销什么、撤到哪、是否已共享&quot;选择不同的命令。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li><a href="/Encyclopedia/50-工具与工程/Git/Git分支与合并">Git分支与合并</a>：理解合并、HEAD、分支。</li><li><a href="/Encyclopedia/50-工具与工程/Git/Git基础操作">Git基础操作</a>：理解三个区、<code>status</code>、<code>diff</code>。</li><li><a href="/Encyclopedia/50-工具与工程/Git/Git远程仓库">Git远程仓库</a>（撤销已推送的提交时需要）。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>团队协作时，两个人改同一个配置文件的同一行是迟早的事；一个人也会手滑：改错文件、提交了不该提交的、<code>reset --hard</code> 之后发现丢了东西。Git 的好处是几乎每一步都有退路，前提是你知道<strong>该用哪一个</strong>。</p><h2 id="一、合并冲突" tabindex="-1">一、合并冲突 <a class="header-anchor" href="#一、合并冲突" aria-label="Permalink to &quot;一、合并冲突&quot;">​</a></h2><h3 id="冲突是怎么产生的" tabindex="-1">冲突是怎么产生的 <a class="header-anchor" href="#冲突是怎么产生的" aria-label="Permalink to &quot;冲突是怎么产生的&quot;">​</a></h3><p>分支 <code>main</code> 和 <code>dev-a</code> 都从同一个提交出发，都修改了 <code>config.ini</code> 的同一行 <code>port=5000</code>：main 改成 9000，dev-a 改成 8080。合并时 Git 面对&quot;同一行，两个不同的新值&quot;，只能求助于你。</p><h3 id="实际制造并解决" tabindex="-1">实际制造并解决 <a class="header-anchor" href="#实际制造并解决" aria-label="Permalink to &quot;实际制造并解决&quot;">​</a></h3><p>准备：<code>config.ini</code> 内容为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>name=MiniMES</span></span>
<span class="line"><span>port=5000</span></span>
<span class="line"><span>debug=false</span></span></code></pre></div><p>在 dev-a 分支把 port 改成 8080 并提交；回到 main 把 port 改成 9000 并提交。然后合并：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git merge dev-a</span></span>
<span class="line"><span>Auto-merging config.ini</span></span>
<span class="line"><span>CONFLICT (content): Merge conflict in config.ini</span></span>
<span class="line"><span>Automatic merge failed; fix conflicts and then commit the result.</span></span></code></pre></div><p>先别慌，看状态：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git status</span></span>
<span class="line"><span>On branch main</span></span>
<span class="line"><span>You have unmerged paths.</span></span>
<span class="line"><span>  (fix conflicts and run &quot;git commit&quot;)</span></span>
<span class="line"><span>  (use &quot;git merge --abort&quot; to abort the merge)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Unmerged paths:</span></span>
<span class="line"><span>  (use &quot;git add &lt;file&gt;...&quot; to mark resolution)</span></span>
<span class="line"><span>	both modified:   config.ini</span></span>
<span class="line"><span></span></span>
<span class="line"><span>no changes added to commit (use &quot;git add&quot; and/or &quot;git commit -a&quot;)</span></span></code></pre></div><p><code>both modified</code> = 双方都改了。提示里有两条路：解决后 <code>git commit</code>，或者 <code>git merge --abort</code> 放弃合并。打开文件，Git 已经把两个版本都写进去并用标记隔开：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>name=MiniMES</span></span>
<span class="line"><span>&lt;&lt;&lt;&lt;&lt;&lt;&lt; HEAD</span></span>
<span class="line"><span>port=9000</span></span>
<span class="line"><span>=======</span></span>
<span class="line"><span>port=8080</span></span>
<span class="line"><span>&gt;&gt;&gt;&gt;&gt;&gt;&gt; dev-a</span></span>
<span class="line"><span>debug=false</span></span></code></pre></div><p>怎么读：</p><ul><li><code>&lt;&lt;&lt;&lt;&lt;&lt;&lt; HEAD</code> 到 <code>=======</code>：<strong>当前分支</strong>（你站着的 main）的版本。</li><li><code>=======</code> 到 <code>&gt;&gt;&gt;&gt;&gt;&gt;&gt; dev-a</code>：<strong>被合并进来的分支</strong>（dev-a）的版本。</li><li>没冲突的行（<code>name=...</code>、<code>debug=...</code>）已自动合并好，不带标记。</li></ul><p><code>git diff</code> 也能看到这个&quot;组合差异&quot;（带 <code>++</code> 两列）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git diff</span></span>
<span class="line"><span>diff --cc config.ini</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span> name=MiniMES</span></span>
<span class="line"><span>++&lt;&lt;&lt;&lt;&lt;&lt;&lt; HEAD</span></span>
<span class="line"><span> +port=9000</span></span>
<span class="line"><span>++=======</span></span>
<span class="line"><span>+ port=8080</span></span>
<span class="line"><span>++&gt;&gt;&gt;&gt;&gt;&gt;&gt; dev-a</span></span>
<span class="line"><span> debug=false</span></span></code></pre></div><p><strong>解决步骤</strong>：</p><ol><li>用编辑器打开文件，<strong>删掉三种标记行</strong>，只留下最终想要的内容。可以选一边、选另一边、或者两边融合。本例决定保留 8080：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>name=MiniMES</span></span>
<span class="line"><span>port=8080</span></span>
<span class="line"><span>debug=false</span></span></code></pre></div><ol start="2"><li><code>git add config.ini</code>（告诉 Git &quot;这个冲突我处理完了&quot;）。</li><li><code>git commit</code>（合并提交，可用 <code>-m</code> 写说明）：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git add config.ini</span></span>
<span class="line"><span>$ git commit -m &quot;Merge dev-a, keep port 8080&quot;</span></span>
<span class="line"><span>[main cff85e7] Merge dev-a, keep port 8080</span></span>
<span class="line"><span>$ git log --oneline --graph</span></span>
<span class="line"><span>*   cff85e7 Merge dev-a, keep port 8080</span></span>
<span class="line"><span>|\\</span></span>
<span class="line"><span>| * 11058b6 A: port 8080</span></span>
<span class="line"><span>* | 8eb1841 main: port 9000</span></span>
<span class="line"><span>|/</span></span>
<span class="line"><span>* d8afae5 add config</span></span></code></pre></div><p><strong>重要检查</strong>：提交前确认文件里<strong>没有残留</strong> <code>&lt;&lt;&lt;&lt;&lt;&lt;&lt;</code>、<code>=======</code>、<code>&gt;&gt;&gt;&gt;&gt;&gt;&gt;</code>。残留的标记会被当成正常内容提交进去，配置文件或代码就坏了。可以 <code>git grep -n &quot;&lt;&lt;&lt;&lt;&lt;&lt;&lt;&quot;</code> 搜一下。</p><h3 id="不想解决了-abort" tabindex="-1">不想解决了：abort <a class="header-anchor" href="#不想解决了-abort" aria-label="Permalink to &quot;不想解决了：abort&quot;">​</a></h3><p>再制造一次冲突（dev-b 把 port 改成 1111，main 改成 2222），合并后发现不想处理：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git merge dev-b</span></span>
<span class="line"><span>Auto-merging config.ini</span></span>
<span class="line"><span>CONFLICT (content): Merge conflict in config.ini</span></span>
<span class="line"><span>Automatic merge failed; fix conflicts and then commit the result.</span></span>
<span class="line"><span>$ git merge --abort</span></span>
<span class="line"><span>$ git status</span></span>
<span class="line"><span>On branch main</span></span>
<span class="line"><span>nothing to commit, working tree clean</span></span></code></pre></div><p><code>--abort</code> 把仓库恢复到合并之前的样子，毫发无损。</p><h3 id="避免和减少冲突" tabindex="-1">避免和减少冲突 <a class="header-anchor" href="#避免和减少冲突" aria-label="Permalink to &quot;避免和减少冲突&quot;">​</a></h3><ul><li>小步提交，经常 <code>pull</code> 同步，别让分支离主线太远。</li><li>团队分工让不同人改不同文件；公共配置文件一次只让一个人改。</li><li>代码格式化规则统一，避免&quot;因为缩进被改全文件&quot;造成的虚假冲突（见 <a href="/Encyclopedia/50-工具与工程/代码规范与重构">代码规范与重构</a>）。</li><li>二进制文件（Excel、图片）无法行级合并，冲突时只能整体选一边：<code>git checkout --ours 文件</code> 或 <code>--theirs 文件</code>。</li></ul><h2 id="二、撤销-先判断-东西现在在哪" tabindex="-1">二、撤销：先判断&quot;东西现在在哪&quot; <a class="header-anchor" href="#二、撤销-先判断-东西现在在哪" aria-label="Permalink to &quot;二、撤销：先判断&quot;东西现在在哪&quot;&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的情况</th><th>用什么</th></tr></thead><tbody><tr><td>工作区改乱了，想放弃修改，回到暂存区/上次提交的样子</td><td><code>git restore 文件</code></td></tr><tr><td>已 <code>add</code> 但想取消暂存（改动保留在工作区）</td><td><code>git restore --staged 文件</code></td></tr><tr><td>刚提交，提交信息写错/漏了一个文件</td><td><code>git commit --amend</code></td></tr><tr><td>已提交但<strong>还没推送</strong>，想退回去重做</td><td><code>git reset</code></td></tr><tr><td>已提交且<strong>已推送/已共享</strong>，想抵消它</td><td><code>git revert</code></td></tr><tr><td>怎么都找不到自己的提交了</td><td><code>git reflog</code></td></tr><tr><td>手上活没做完，想先切去干别的</td><td><code>git stash</code></td></tr></tbody></table><h3 id="restore-撤销工作区-暂存区的改动" tabindex="-1">restore：撤销工作区/暂存区的改动 <a class="header-anchor" href="#restore-撤销工作区-暂存区的改动" aria-label="Permalink to &quot;restore：撤销工作区/暂存区的改动&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ echo &quot;oops&quot; &gt;&gt; u.txt</span></span>
<span class="line"><span>$ git status -s</span></span>
<span class="line"><span> M u.txt</span></span>
<span class="line"><span>$ git restore u.txt</span></span>
<span class="line"><span>$ cat u.txt</span></span>
<span class="line"><span>line1</span></span></code></pre></div><p><code>restore u.txt</code> 把工作区的文件恢复成暂存区（没暂存则是上次提交）的样子。<strong>这一步会永久丢掉未提交的修改，Git 无法找回</strong>（没提交过，reflog 也没有）。</p><p>取消暂存：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ echo &quot;tmp&quot; &gt;&gt; u.txt</span></span>
<span class="line"><span>$ git add u.txt</span></span>
<span class="line"><span>$ git status -s</span></span>
<span class="line"><span>M  u.txt</span></span>
<span class="line"><span>$ git restore --staged u.txt</span></span>
<span class="line"><span>$ git status -s</span></span>
<span class="line"><span> M u.txt</span></span></code></pre></div><p>改动从左列（暂存）回到右列（工作区），内容没丢。</p><p>从历史取回旧版本的某个文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git restore --source=HEAD~1 f.txt</span></span>
<span class="line"><span>$ cat f.txt</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>$ git status -s</span></span>
<span class="line"><span> M f.txt</span></span></code></pre></div><p><code>--source=HEAD~1</code> 指&quot;上一个提交里的版本&quot;；取回后在工作区表现为一处修改，还要自己 add/commit 才算数。</p><p>另一个相关命令 <code>git clean</code> 删除<strong>未跟踪</strong>的文件，因为不可恢复，先用 <code>-n</code>（dry run，只预览）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git clean -n</span></span>
<span class="line"><span>Would remove junk.txt</span></span>
<span class="line"><span>$ git clean -f</span></span>
<span class="line"><span>Removing junk.txt</span></span></code></pre></div><h3 id="amend-修补最近一次提交" tabindex="-1">amend：修补最近一次提交 <a class="header-anchor" href="#amend-修补最近一次提交" aria-label="Permalink to &quot;amend：修补最近一次提交&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git commit --amend -m &quot;add b.txt&quot;        # 改提交说明</span></span>
<span class="line"><span>$ git add c.txt</span></span>
<span class="line"><span>$ git commit --amend --no-edit               # 把漏掉的文件补进上一次提交，说明不变</span></span>
<span class="line"><span>$ git show --stat --oneline HEAD</span></span>
<span class="line"><span>e199bf9 add b.txt</span></span>
<span class="line"><span> b.txt | 1 +</span></span>
<span class="line"><span> c.txt | 1 +</span></span>
<span class="line"><span> 2 files changed, 2 insertions(+)</span></span></code></pre></div><p><code>amend</code> 会产生<strong>新的提交</strong>取代旧的（哈希变），所以和 rebase 一样：<strong>已推送的提交不要 amend</strong>。</p><h3 id="reset-移动分支指针-三种模式" tabindex="-1">reset：移动分支指针（三种模式） <a class="header-anchor" href="#reset-移动分支指针-三种模式" aria-label="Permalink to &quot;reset：移动分支指针（三种模式）&quot;">​</a></h3><p><code>reset</code> 把当前分支（和 HEAD）移到另一个提交。三种模式区别在&quot;同时动哪些区&quot;：</p><table tabindex="0"><thead><tr><th>模式</th><th>分支指针</th><th>暂存区</th><th>工作区</th><th>适用</th></tr></thead><tbody><tr><td><code>--soft</code></td><td>移动</td><td>不动（保留为已暂存）</td><td>不动</td><td>想把几个提交合并成一个</td></tr><tr><td><code>--mixed</code>（默认）</td><td>移动</td><td>重置</td><td>不动</td><td>撤销提交和 add，保留改动</td></tr><tr><td><code>--hard</code></td><td>移动</td><td>重置</td><td><strong>重置</strong></td><td>彻底丢掉改动，危险</td></tr></tbody></table><p>实验：连续 3 次提交（每次给 <code>u.txt</code> 加一行 <code>c1</code>/<code>c2</code>/<code>c3</code>）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git log --oneline -5</span></span>
<span class="line"><span>6a6add8 commit c3</span></span>
<span class="line"><span>898d4d2 commit c2</span></span>
<span class="line"><span>391185d commit c1</span></span>
<span class="line"><span>6dc1977 add u</span></span>
<span class="line"><span>c0509bf main: port 2222</span></span></code></pre></div><p><code>HEAD~1</code> 的意思是&quot;HEAD 的上一个&quot;。</p><p><strong>soft</strong>：退一步，改动还在暂存区：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git reset --soft HEAD~1</span></span>
<span class="line"><span>$ git status -s</span></span>
<span class="line"><span>M  u.txt</span></span>
<span class="line"><span>$ git commit -m &quot;commit c3 redo&quot;</span></span>
<span class="line"><span>[main f91128b] commit c3 redo</span></span></code></pre></div><p><strong>mixed</strong>：退一步，改动退回到工作区（未暂存）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git reset --mixed HEAD~1</span></span>
<span class="line"><span>Unstaged changes after reset:</span></span>
<span class="line"><span>M	u.txt</span></span>
<span class="line"><span>$ git status -s</span></span>
<span class="line"><span> M u.txt</span></span>
<span class="line"><span>$ cat u.txt</span></span>
<span class="line"><span>line1</span></span>
<span class="line"><span>c1</span></span>
<span class="line"><span>c2</span></span>
<span class="line"><span>c3</span></span></code></pre></div><p>文件内容还是有 <code>c3</code>，只是不在提交里也不在暂存区了。</p><p><strong>hard</strong>：改动彻底消失：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git add -A &amp;&amp; git commit -m &quot;commit c3 again&quot;</span></span>
<span class="line"><span>$ git reset --hard HEAD~1</span></span>
<span class="line"><span>HEAD is now at 898d4d2 commit c2</span></span>
<span class="line"><span>$ cat u.txt</span></span>
<span class="line"><span>line1</span></span>
<span class="line"><span>c1</span></span>
<span class="line"><span>c2</span></span></code></pre></div><p><code>c3</code> 从历史和文件里都不见了。看起来永远丢了——但是下面的 <code>reflog</code> 能救。</p><h3 id="reflog-救命的-操作日志" tabindex="-1">reflog：救命的&quot;操作日志&quot; <a class="header-anchor" href="#reflog-救命的-操作日志" aria-label="Permalink to &quot;reflog：救命的&quot;操作日志&quot;&quot;">​</a></h3><p><code>git log</code> 看的是分支历史；<code>git reflog</code> 记录的是<strong>HEAD 每一次移动</strong>（提交、切换、reset、merge ...），默认保留几十天（默认值约 90 天，可配置；此值依据常识，未在本机验证）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git reflog -8</span></span>
<span class="line"><span>898d4d2 HEAD@{0}: reset: moving to HEAD~1</span></span>
<span class="line"><span>89a2f26 HEAD@{1}: commit: commit c3 again</span></span>
<span class="line"><span>898d4d2 HEAD@{2}: reset: moving to HEAD~1</span></span>
<span class="line"><span>f91128b HEAD@{3}: commit: commit c3 redo</span></span>
<span class="line"><span>898d4d2 HEAD@{4}: reset: moving to HEAD~1</span></span>
<span class="line"><span>6a6add8 HEAD@{5}: commit: commit c3</span></span>
<span class="line"><span>898d4d2 HEAD@{6}: commit: commit c2</span></span>
<span class="line"><span>391185d HEAD@{7}: commit: commit c1</span></span></code></pre></div><p><code>HEAD@{1}</code> 就是&quot;HEAD 上一次所在的位置&quot;，也就是被 <code>--hard</code> 丢掉前的 <code>89a2f26</code>。退回去：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git reset --hard HEAD@{1}</span></span>
<span class="line"><span>HEAD is now at 89a2f26 commit c3 again</span></span>
<span class="line"><span>$ cat u.txt</span></span>
<span class="line"><span>line1</span></span>
<span class="line"><span>c1</span></span>
<span class="line"><span>c2</span></span>
<span class="line"><span>c3</span></span></code></pre></div><p><code>c3</code> 回来了。<strong>只要改动曾经被 commit 过，几乎都能用 reflog 找回</strong>；没 commit 过的工作区改动（比如 <code>restore</code>、<code>clean</code>、<code>reset --hard</code> 抹掉的未提交修改）找不回。这就是&quot;勤提交&quot;的意义。</p><p>再一个典型场景，误删分支：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git branch -D risky</span></span>
<span class="line"><span>Deleted branch risky (was cb0dcb0).</span></span>
<span class="line"><span>$ git reflog -4</span></span>
<span class="line"><span>e199bf9 HEAD@{0}: checkout: moving from risky to main</span></span>
<span class="line"><span>cb0dcb0 HEAD@{1}: commit: risky work</span></span>
<span class="line"><span>e199bf9 HEAD@{2}: checkout: moving from main to risky</span></span>
<span class="line"><span>e199bf9 HEAD@{3}: reset: moving to HEAD</span></span>
<span class="line"><span>$ git branch risky-back HEAD@{1}</span></span>
<span class="line"><span>$ git branch -v</span></span>
<span class="line"><span>* main       e199bf9 add b.txt</span></span>
<span class="line"><span>  risky-back cb0dcb0 risky work</span></span></code></pre></div><p><code>-D</code> 提示里就印着被删分支的哈希（<code>was cb0dcb0</code>），用 <code>git branch 新名字 哈希</code> 立刻复活。</p><h3 id="revert-用-反向提交-抵消已共享的提交" tabindex="-1">revert：用&quot;反向提交&quot;抵消已共享的提交 <a class="header-anchor" href="#revert-用-反向提交-抵消已共享的提交" aria-label="Permalink to &quot;revert：用&quot;反向提交&quot;抵消已共享的提交&quot;">​</a></h3><p>已经 push 的提交，别人可能已经基于它工作了，不能 reset 抹掉。<code>revert</code> 的做法是新增一个提交，其内容恰好是那次提交的逆操作，历史只增不改：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git revert HEAD --no-edit</span></span>
<span class="line"><span>[main 6c8ee1d] Revert &quot;commit c3 again&quot;</span></span>
<span class="line"><span> 1 file changed, 1 deletion(-)</span></span>
<span class="line"><span>$ git log --oneline -5</span></span>
<span class="line"><span>6c8ee1d Revert &quot;commit c3 again&quot;</span></span>
<span class="line"><span>89a2f26 commit c3 again</span></span>
<span class="line"><span>898d4d2 commit c2</span></span>
<span class="line"><span>391185d commit c1</span></span>
<span class="line"><span>6dc1977 add u</span></span>
<span class="line"><span>$ cat u.txt</span></span>
<span class="line"><span>line1</span></span>
<span class="line"><span>c1</span></span>
<span class="line"><span>c2</span></span></code></pre></div><p>c3 的内容没了，但 &quot;commit c3 again&quot; 这条历史还在，别人 <code>pull</code> 时只是多收到一个新提交，不会出任何冲突。</p><h3 id="reset-与-revert-怎么选" tabindex="-1">reset 与 revert 怎么选 <a class="header-anchor" href="#reset-与-revert-怎么选" aria-label="Permalink to &quot;reset 与 revert 怎么选&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>reset</th><th>revert</th></tr></thead><tbody><tr><td>历史</td><td>改写（提交消失）</td><td>只追加</td></tr><tr><td>已 push 的提交</td><td>不要用（除非全员知情并强推）</td><td>正确做法</td></tr><tr><td>本地私有提交</td><td>适合</td><td>也行但啰嗦</td></tr></tbody></table><h3 id="stash-先把手上的活藏起来" tabindex="-1">stash：先把手上的活藏起来 <a class="header-anchor" href="#stash-先把手上的活藏起来" aria-label="Permalink to &quot;stash：先把手上的活藏起来&quot;">​</a></h3><p>正在改东西，突然要切分支处理急事，又不想提交半成品：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ echo &quot;wip&quot; &gt;&gt; a.txt</span></span>
<span class="line"><span>$ git stash</span></span>
<span class="line"><span>Saved working directory and index state WIP on main: e199bf9 add b.txt</span></span>
<span class="line"><span>$ git status -s</span></span>
<span class="line"><span>$ git stash list</span></span>
<span class="line"><span>stash@{0}: WIP on main: e199bf9 add b.txt</span></span>
<span class="line"><span>$ git stash pop</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>	modified:   a.txt</span></span>
<span class="line"><span>Dropped refs/stash@{0} (8633d9f605c27e5433e0fee2b084ee0088fe25ed)</span></span></code></pre></div><p><code>stash</code> 把工作区和暂存区改动存到一个栈里，让目录回到干净状态；<code>stash pop</code> 取回并删除那条记录。新文件（未跟踪）默认不会被 stash，需要 <code>git stash -u</code>。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><p>在空文件夹 <code>undo-lab</code> 里 <code>git init -b main</code>，设置本仓库 user，然后：</p><p><strong>实验 A：制造并解决冲突</strong></p><ol><li>创建 <code>config.ini</code> 写三行（<code>name=X</code>、<code>port=5000</code>、<code>debug=false</code>），提交。</li><li><code>git switch -c dev-a</code>，把 port 改成 8080，提交。</li><li><code>git switch main</code>，把 port 改成 9000，提交。</li><li><code>git merge dev-a</code>，确认出现 <code>CONFLICT</code>，<code>git status</code> 看到 <code>both modified</code>。</li><li>编辑文件删掉标记，保留 8080。<code>git add config.ini</code>，<code>git commit -m &quot;resolve&quot;</code>。</li><li><code>git log --oneline --graph</code> 应看到分叉汇合图。</li></ol><p><strong>实验 B：reset 三种模式与 reflog</strong></p><ol><li>新建 <code>u.txt</code> 提交，再连续提交三次追加 <code>c1 c2 c3</code>。</li><li>依次试 <code>reset --soft HEAD~1</code>（用 <code>git status -s</code> 观察）、再 commit；<code>reset --mixed HEAD~1</code>；<code>git add -A &amp;&amp; git commit</code>；<code>reset --hard HEAD~1</code>。</li><li>用 <code>git reflog</code> 找到 <code>--hard</code> 之前的位置，<code>git reset --hard HEAD@{1}</code> 找回，<code>cat u.txt</code> 确认。</li></ol><p><strong>实验 C：revert</strong>：对最新提交执行 <code>git revert HEAD --no-edit</code>，确认内容被抵消而历史多了一条。</p><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><ul><li><strong>冲突后一直提示 <code>You have unmerged paths</code></strong>：忘了 <code>git add</code> 已解决的文件。</li><li><strong>commit 时被 <code>Committing is not possible because you have unmerged files</code> 拒绝</strong>：同上，还有文件未标记为已解决。<code>git status</code> 看红色的 <code>both modified</code> 项。</li><li><strong><code>reset --hard</code> 前没看清</strong>：先 <code>git status</code>/<code>git stash</code> 确认没有未提交的重要改动，因为它们找不回。</li><li><strong>对已 push 的提交 <code>reset</code> + 强制推送</strong>：会让同事的本地历史与远程对不上。要么用 <code>revert</code>，要么先和团队沟通；强制推送请用 <code>--force-with-lease</code>（见 <a href="/Encyclopedia/50-工具与工程/Git/Git远程仓库">Git远程仓库</a>）。</li><li><strong>rebase 时的冲突</strong>：解决后用 <code>git add</code> 然后 <code>git rebase --continue</code>（不是 commit）；想放弃用 <code>git rebase --abort</code>。</li><li><strong>一次改了很多无关内容</strong>：养成小步提交习惯，出了问题定位和回退都容易。</li><li><strong>VS / VS Code 里的图形化冲突工具</strong>：它们本质上也是改这些标记，原理一致。</li></ul><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><p><strong>1.</strong> 冲突标记里 <code>HEAD</code> 一侧和另一侧分别是谁的？ 答：<code>&lt;&lt;&lt;&lt;&lt;&lt;&lt; HEAD</code> 到 <code>=======</code> 是你当前所在分支的版本；之后到 <code>&gt;&gt;&gt;&gt;&gt;&gt;&gt; 分支名</code> 是被合并进来的分支的版本。</p><p><strong>2.</strong> 我 <code>git add</code> 了一个不想提交的文件，怎么取消但保留修改？ 答：<code>git restore --staged 文件</code>。</p><p><strong>3.</strong> 我 <code>git restore 文件</code> 之后发现改错了，能找回吗？ 答：不能（改动从未被提交或暂存）。这是 <code>restore</code> 的风险。</p><p><strong>4.</strong> <code>reset --soft</code>、<code>--mixed</code>、<code>--hard</code> 的区别？ 答：都会移动分支指针；soft 保留暂存区和工作区，mixed 清空暂存区但保留工作区，hard 两者都重置。</p><p><strong>5.</strong> 同事已经拉取了我的错误提交，我该用 reset 还是 revert？ 答：revert。reset 会改写历史，导致同事的仓库与远程不一致。</p><p><strong>6.</strong> <code>git reset --hard</code> 后丢了刚提交的内容，怎么办？ 答：<code>git reflog</code> 找到那次提交的哈希，<code>git reset --hard 哈希</code> 回去。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>冲突 = 同一处被双方修改；读懂 <code>&lt;&lt;&lt;&lt;&lt;&lt;&lt;</code> <code>=======</code> <code>&gt;&gt;&gt;&gt;&gt;&gt;&gt;</code>，编辑、<code>add</code>、<code>commit</code> 三步解决，不想解决就 <code>merge --abort</code>。</li><li>撤销命令按&quot;改动在哪个区、是否已共享&quot;选：<code>restore</code>（工作区/暂存区）、<code>amend</code>（最近一次提交）、<code>reset</code>（私有历史）、<code>revert</code>（已共享历史）。</li><li><code>reflog</code> 记录 HEAD 的每次移动，是提交过的内容的后悔药；没提交过的改动没救，所以勤提交。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git基础操作">Git基础操作</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git分支与合并">Git分支与合并</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git远程仓库">Git远程仓库</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git工作流">Git工作流</a>、<a href="/Encyclopedia/50-工具与工程/调试与排错方法">调试与排错方法</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>Pro Git 重置揭秘：<a href="https://git-scm.com/book/zh/v2/Git-%E5%B7%A5%E5%85%B7-%E9%87%8D%E7%BD%AE%E6%8F%AD%E7%A7%98" target="_blank" rel="noreferrer">https://git-scm.com/book/zh/v2/Git-工具-重置揭秘</a></li><li>git reflog 文档：<a href="https://git-scm.com/docs/git-reflog" target="_blank" rel="noreferrer">https://git-scm.com/docs/git-reflog</a></li><li>git restore 文档：<a href="https://git-scm.com/docs/git-restore" target="_blank" rel="noreferrer">https://git-scm.com/docs/git-restore</a></li></ul>`,106)])])}const u=s(p,[["render",o]]);export{h as __pageData,u as default};
